package com.worksphere.service;
import com.worksphere.dto.application.*; import com.worksphere.entity.*; import com.worksphere.repository.*; import com.worksphere.exception.*; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ApplicationService {private final ApplicationRepository apps;private final JobRepository jobs;private final UserService users;private final MatchingService matching;private final NotificationService notifications;private final WorkerProfileRepository wp;private final WorkerSkillRepository ws;private final CommitmentRepository commitments;public ApplicationService(ApplicationRepository a,JobRepository j,UserService u,MatchingService m,NotificationService n,WorkerProfileRepository w,WorkerSkillRepository sk,CommitmentRepository c){apps=a;jobs=j;users=u;matching=m;notifications=n;wp=w;ws=sk;commitments=c;} public ApplicationResponse apply(Authentication a,ApplicationRequest r){User w=users.current(a);if(w.role!=Role.JOB_SEEKER)throw new UnauthorizedActionException("Only job seekers can apply");Job j=jobs.findById(r.jobId()).orElseThrow(()->new ResourceNotFoundException("Job not found"));if(j.status!=JobStatus.OPEN)throw new BadRequestException("Applications are closed");if(apps.findByJobIdAndWorkerId(j.id,w.id).isPresent())throw new DuplicateApplicationException("Already applied");Application x=new Application();x.job=j;x.worker=w;x.coverMessage=r.coverMessage();x=apps.save(x);notifications.send(j.employer,NotificationType.APPLICATION,w.fullName+" applied for "+j.title);return to(x);} public List<ApplicationResponse> mine(Authentication a){return apps.findByWorkerIdOrderByAppliedAtDesc(users.current(a).id).stream().map(this::to).toList();} public List<ApplicationResponse> forJob(Long jobId,Authentication a){User u=users.current(a);Job j=jobs.findById(jobId).orElseThrow();if(!j.employer.id.equals(u.id))throw new UnauthorizedActionException("Not your job");return apps.findByJobIdOrderByAppliedAtAsc(jobId).stream().map(this::to).toList();} public List<ApplicationResponse> employerAll(Authentication a){User u=users.current(a);return jobs.findByEmployerIdOrderByCreatedAtDesc(u.id).stream().flatMap(j->apps.findByJobIdOrderByAppliedAtAsc(j.id).stream()).map(this::to).toList();} public void withdraw(Long id,Authentication a){Application x=apps.findById(id).orElseThrow();if(!x.worker.id.equals(users.current(a).id))throw new UnauthorizedActionException("Not your application");if(x.status!=ApplicationStatus.PENDING)throw new BadRequestException("Only pending applications can be withdrawn");x.status=ApplicationStatus.WITHDRAWN;apps.save(x);} public void select(Long id,Authentication a){Application x=apps.findById(id).orElseThrow();User e=users.current(a);if(!x.job.employer.id.equals(e.id))throw new UnauthorizedActionException("Not your job");if(x.status!=ApplicationStatus.PENDING)throw new BadRequestException("Application is not pending");x.status=ApplicationStatus.SELECTED;apps.save(x);x.job.workersSelected++;if(x.job.workersSelected>=x.job.workersRequired)x.job.status=JobStatus.FULL;jobs.save(x.job);Commitment c=new Commitment();c.application=x;c.job=x.job;c.worker=x.worker;c.employer=e;c.depositStatus=x.job.depositRequired?DepositStatus.PENDING:DepositStatus.NOT_REQUIRED;commitments.save(c);notifications.send(x.worker,NotificationType.SELECTION,"You were selected for "+x.job.title);} public void reject(Long id,Authentication a){Application x=apps.findById(id).orElseThrow();if(!x.job.employer.id.equals(users.current(a).id))throw new UnauthorizedActionException("Not your job");x.status=ApplicationStatus.REJECTED;apps.save(x);notifications.send(x.worker,NotificationType.APPLICATION,"Your application for "+x.job.title+" was rejected");} private ApplicationResponse to(Application x){WorkerProfile p=wp.findByUserId(x.worker.id).orElse(null);List<String> sk=p==null?List.of():ws.findByWorkerId(p.id).stream().map(s->s.skill.name).toList();return new ApplicationResponse(x.id,x.job.id,x.job.title,x.job.location,x.job.jobDate,x.worker.fullName,p==null?0:p.rating,sk,matching.score(x.job,x.worker),x.coverMessage,x.status.name(),x.appliedAt);} }
